# Final hypothesis for row 0:
# Output[0][c] = Input[c]  (original input)
# Output[r][c] = Input[c - r] if c > n, else bg_val

def generate_output_v2(input_row, bg_val, height):
    n = len([x for x in input_row if x == bg_val])
    # Actually let's compute n as consecutive prefix of bg_val
    n = 0
    for i in range(len(input_row)):
        if i == 0 or input_row[i] == bg_val:
            if i == 0:
                n = 1
            elif input_row[i] == bg_val:
                n += 1
            else:
                break
        else:
            break

    print(f"n = {n}, bg_val = {bg_val}")

    output_rows = []
    for r in range(height):
        out_row = []
        for c in range(len(input_row)):
            if r == 0:
                out_row.append(input_row[c])
            else:
                if c <= n + r - 1:
                    out_row.append(bg_val)
                else:
                    idx = c - r
                    if idx < n:
                        out_row.append(bg_val)
                    else:
                        out_row.append(input_row[idx])
        output_rows.append(out_row)
    return output_rows

input_test = [5, 5, 5, 4, 4, 9, 7, 4, 7, 4, 7, 4, 9, 4, 4, 4]
bg_val = 4  # Most common / background
height = 8  # width / 2

result = generate_output_v2(input_test, bg_val, height)

